//---------------------------------------------------
//-- Resetter
//-- - - - - - - - - - - - - - - - - - - - - - - - --
//-- Reset the system after N clock ticks
//---------------------------------------------------

module Resetter__v2cdee4_v2e88b5 #(
 parameter N_clk_ticks = 0
) (
 input clk,
 input en,
 output reset
);
 
 reg [8:0] counter =0; 
 reg reset_out = 0;
 
 assign reset = reset_out;
 
 always @(posedge clk) begin
     if (en) begin
     if (counter < N_clk_ticks-1) 
     begin
         counter <= counter + 1;
         reset_out <= 1;  
     end 
     else begin
         if (counter == (N_clk_ticks-1))
         begin
             counter <= counter + 1;
             reset_out <=0;
         end
         else begin 
             if (counter == (N_clk_ticks))
             begin
                 counter <= counter + 1;
                 reset_out <=0;
             end
             else 
                 begin
                 if (counter == (N_clk_ticks+1))
                 begin
                 reset_out <=1;
                 end
             end
         end
     end
     end
 end
endmodule
