//---------------------------------------------------
//-- register decoder
//-- - - - - - - - - - - - - - - - - - - - - - - - --
//-- reister  to interact with the decoder
//---------------------------------------------------

module register_decoder__vc24b42_v91011c #(
 parameter ADDR = 0
) (
 input clk,
 input reset,
 input SS,
 input [7:0] data_from_master,
 input rcv,
 input [15:0] data_from_fpga,
 input button,
 output load,
 output [7:0] data_out,
 output [7:0] register_out
);
 //      +------+
 //      | IDLE |
 //      +------+                                    
 //         |                                        
 //         | rcv && bytes_from_master_counter == 0  
  //        v                                        
 //    +------------+                                
 //    | ADDR_MODUL |                            
 //    +------------+                                
 //         |                                    
 //         | received_addr == ADDR                  
 //         |--------------------------------------->|
 //         |                                        |
 //         | rw == 1                                | rw == 0
 //         v                                        v
 //    +-------+                                +--------+
 //    | READ  |                                | WRITE  |
 //    +-------+                                +--------+
 //         |                                       |
 //         | bytes_from_master_counter >= 16       |
 //         |-------------------------------------->|
 //         |                                       |
 //         +---------------------------------------+
 //            back to idel per restet or SS is high
 //halo
 
 
 parameter IDLE          = 3'b000,
           ADDR_MODUL    = 3'b001,
           READ          = 3'b010,
           WRITE         = 3'b110;
 
 
 reg [2:0]state;
 reg [7:0]registers; // 16 registers of 8-bit width
 reg [4:0]bytes_from_master_counter;
 reg [7:0]data_pointer;
 reg rw;
 reg [5:0]received_addr;
 reg load_data_on_slave_ready;
 assign load = load_data_on_slave_ready;
 reg [7:0]data_from_slave;
 assign data_out = data_from_slave;
 reg load_slave_o;
 
 // register dummy
 
 assign register_out = registers;
 
 
 
 always @(posedge clk) begin
     if (!reset) begin
         state <= IDLE;
         bytes_from_master_counter <= 0;
         data_pointer <= 0;
         received_addr <= 0;
         load_data_on_slave_ready <= 0;
         data_from_slave <= 0;
         rw <= 0;
         registers<=8'h00;
         load_slave_o <= 0;
     end else if (SS) begin    // reset
         state <= IDLE;
         bytes_from_master_counter <= 0;
         data_pointer <= 0;
         received_addr <= 0;
         load_data_on_slave_ready <= 0;
         data_from_slave <= 0;
         rw <= 0;
         load_slave_o <= 0;
     end else if (rcv) begin // reset and ~SS 
         bytes_from_master_counter <= bytes_from_master_counter + 1;
         
         case(state)
         
         IDLE:begin
             rw <= data_from_master[7];
             received_addr <= data_from_master[5:0];
             data_pointer <= 0;
             load_data_on_slave_ready <= 1;
             load_slave_o <= 0;
             if (bytes_from_master_counter == 0)
                 state <= ADDR_MODUL;
             else
                 state <= IDLE;
         end
         
         ADDR_MODUL:begin
             if (received_addr == ADDR) begin
                 data_pointer <= data_from_master[7:0];
                 if (data_from_master[7:0] == 8'hF0)
                     data_from_slave <= data_from_fpga[15:8];
                 else if (data_from_master[7:0] == 8'hF1)   
                     data_from_slave <= data_from_fpga[7:0];
                 else if (data_from_master[7:0] == 8'hFE)
                     data_from_slave <= {7'h00, button};
                 else if (data_from_master[7:0] == 8'h00)
                     data_from_slave <= registers;
                 else
                     data_from_slave <= 8'hDD;
                     
                 load_data_on_slave_ready <= 1;
                 state <= rw ? READ : WRITE;
             end
             else
                 state <= IDLE;
         end
         
         READ:begin
             data_pointer <= data_pointer + 1;
             data_from_slave <= data_from_fpga[7:0];
             load_data_on_slave_ready <= 1;
             if (bytes_from_master_counter > 4)
             begin
                 data_from_slave <= 0;
                 state <= IDLE;
             end
             else
                 state <= READ;
             
         end
         
         WRITE:begin
             registers <= data_from_master;
             data_pointer <= data_pointer + 1;
             load_slave_o <= 1;
             if (bytes_from_master_counter > 4)
                 state <= IDLE;
             else
                 state <= WRITE;
         end
 
         
         endcase
         end
     else begin
     load_data_on_slave_ready <= 0; 
     end 
 end 
 
endmodule
