//-- 32-Reg-rst: 32 bits Register with reset. Verilog implementation
//---------------------------------------------------

module _32_Reg_rst__vd5bdd7_vb9285f #(
 parameter INI = 0
) (
 input clk,
 input rst,
 input [31:0] d,
 input load,
 output [31:0] q
);
 //-- Generic register with reset
 //-- Number of bits
 localparam N = 32;
 
 //-- Initial value
 reg [N-1:0] qi = INI;
 
 always @(posedge clk)
 begin
 
   //-- Reset has the priority
   if (rst == 1'b1)
     qi <= INI;
     
   else
     //-- The value is load only if  
     //-- load is 1
     if (load == 1'b1)
       qi <= d;
       
   //-- In any other case the reg
   //-- keeps its value
 end
 
 //-- Connect the register with the
 //-- output
 assign q = qi;
 
endmodule
