//---------------------------------------------------

module pulser_register__v57ee5a_v4620cf #(
 parameter ADDR = 0
) (
 input clk,
 input reset,
 input SS,
 input [7:0] data_from_master,
 input rcv,
 output load,
 output [7:0] data_out,
 output lock_register,
 output [159:0] register,
 output busy,
 output [15:0] su_register
);
 //      +------+
 //      | IDLE |
 //      +------+                                    
 //         |                                        
 //         | rcv && bytes_from_master_counter == 0  
  //        v                                        
 //    +------------+                                
 //    | ADDR_MODUL |                            
 //    +------------+                                
 //         |                                    
 //         | received_addr == ADDR                  
 //         |--------------------------------------->|
 //         |                                        |
 //         | rw == 1                                | rw == 0
 //         v                                        v
 //    +-------+                                +--------+
 //    | READ  |                                | WRITE  |
 //    +-------+                                +--------+
 //         |                                       |
 //         | bytes_from_master_counter >= 16       |
 //         |-------------------------------------->|
 //         |                                       |
 //         +---------------------------------------+
 //            back to idel per restet or SS is high
 
 
 
 parameter IDLE          = 3'b000,
           ADDR_MODUL    = 3'b001,
           READ          = 3'b010,
           WRITE         = 3'b110;
           
 parameter max_register = 22;
 
 reg [2:0]state;
 reg signed[7:0]registers[max_register-1:0]; // 20 registers of 8-bit width
 reg [4:0]bytes_from_master_counter;
 reg [7:0]data_pointer;
 reg rw;
 reg lock;
 assign lock_register = lock;
 reg [5:0]received_addr;
 reg load_data_on_slave_ready;
 assign load = load_data_on_slave_ready;
 reg [7:0]data_from_slave;
 assign data_out = data_from_slave;
 
 assign su_register = {registers[20],registers[21]};
 
 assign register = {registers[0],registers[1],registers[2],registers[3],registers[4],
                    registers[5],registers[6],registers[7],registers[8],registers[9],
                    registers[10],registers[11],registers[12],registers[13],registers[14],
                    registers[15],registers[16],registers[17],registers[18],registers[19]};
 reg reg_busy;
 assign busy = reg_busy;
                    
 always @(posedge clk) begin
     if (!reset) begin
         state <= IDLE;
         bytes_from_master_counter <= 0;
         data_pointer <= 0;
         received_addr <= 0;
         load_data_on_slave_ready <= 0;
         data_from_slave <= 0;
         rw <= 0;
         lock <=0;
         reg_busy <=0;
         registers[0]<=8'h00;
         registers[1]<=8'h00;
         registers[2]<=8'h00;
         registers[3]<=8'h00;
         registers[4]<=8'h00;
         registers[5]<=8'h00;
         registers[6]<=8'h00;
         registers[7]<=8'h00;
         registers[8]<=8'h00;
         registers[9]<=8'h00;
         registers[10]<=8'h00;
         registers[11]<=8'h00;
         registers[12]<=8'h00;
         registers[13]<=8'h00;
         registers[14]<=8'h00;
         registers[15]<=8'h00;
         registers[16]<=8'h00;
         registers[17]<=8'h00;
         registers[18]<=8'h00;
         registers[19]<=8'h00;
         
         registers[20]<=8'h00;
         registers[21]<=8'h00;
         
     end else if (SS) begin    // reset
         state <= IDLE;
         bytes_from_master_counter <= 0;
         data_pointer <= 0;
         received_addr <= 0;
         load_data_on_slave_ready <= 0;
         data_from_slave <= 0;
         rw <= 0;
         lock <= 0;
         reg_busy <= 0;
     
     end else if (rcv) begin // reset and ~SS 
         bytes_from_master_counter <= bytes_from_master_counter + 1;
         reg_busy <=1;
         
         case(state)
         
         IDLE:begin
             rw <= data_from_master[7];
             received_addr <= data_from_master[5:0];
             data_pointer <= 0;
             load_data_on_slave_ready <= 1;
             lock <= 0;
             if (bytes_from_master_counter == 0)
                 state <= ADDR_MODUL;
             else
                 state <= IDLE;
         end
         
         ADDR_MODUL:begin
             if (received_addr == ADDR) begin
                 data_pointer <= data_from_master[7:0];
                 data_from_slave <= registers[data_from_master[7:0]];
                 load_data_on_slave_ready <= 1;
                 state <= rw ? READ : WRITE;
                 lock <= 1;
             end
             else
                 state <= IDLE;
         end
         
         READ:begin
             data_from_slave <= registers[data_pointer+1];
             data_pointer <= data_pointer + 1;
             load_data_on_slave_ready <= 1;
             lock <= 1;
             if (bytes_from_master_counter > max_register)
                 state <= IDLE;
             else
                 state <= READ;
             
         end
         
         WRITE:begin
             registers[data_pointer] <= data_from_master;
             data_pointer <= data_pointer + 1;
             lock <= 1;
             if (bytes_from_master_counter > max_register)
                 state <= IDLE;
             else
                 state <= WRITE;
         end
         endcase
         end
     else begin
     load_data_on_slave_ready <= 0; 
     end 
 end 
 
