                 enable_external_serial_data  <= 1'b1;   //6
                 out_external_serial_data     <= 1'b1;   //7
                 enable_external_serial_clock <= 1'b0;   //8
                 out_external_serial_clock    <= 1'b1;   //9
                 lat_dev_addr                 <= 7'd0;   //10
                 lat_reg_addr                 <= 8'd0;   //11
                 lat_mosi                     <= 16'd0;  //12
                 shift_reg                    <= 8'd0;   //13
             end
 
             // ----------------------------------------------------------------
             IDLE: begin
                 // state will be conditionally set                   //0
                 phase                        <= 2'd0;               //1
                 bit_cnt                      <= 3'd0;               //2
                 // ack_latch holds previous value                    //3
                 // busy will be conditionally set                    //4
                 // miso_data holds previous value                    //5
                 enable_external_serial_data  <= 1'b1;               //6
                 out_external_serial_data     <= 1'b1;               //7
                 enable_external_serial_clock <= 1'b0;               //8
                 out_external_serial_clock    <= 1'b1;               //9
                 // lat_dev_addr will be conditionally set            //10
                 // lat_reg_addr will be conditionally set            //11
                 // lat_mosi will be conditionally set                //12
                 // shift_reg holds previous value                    //13
 
                 if (enable) begin
                     state        <= read_write ? R_START : W_START; //0
                     busy         <= 1'b1;                           //4
                     lat_dev_addr <= device_address;                 //10
                     lat_reg_addr <= register_address;               //11
                     lat_mosi     <= mosi_data;                      //12
                 end else begin
                     state <= IDLE;                                  //0
                     busy  <= 1'b0;                                  //4
                     // lat_dev_addr holds previous value             //10
                     // lat_reg_addr holds previous value             //11
                     // lat_mosi holds previous value                 //12
                 end
             end
 
             // ================================================================
             // WRITE BRANCH
             // ================================================================
 
             W_START: begin
                 state                        <= W_ADDR;               //0
                 phase                        <= 2'd0;                 //1
                 bit_cnt                      <= 3'd7;                 //2
                 // ack_latch holds previous value                     //3
                 // busy holds previous value (1'b1)                   //4
                 // miso_data holds previous value                     //5
                 enable_external_serial_data  <= 1'b0;                //6  drive SDA
                 out_external_serial_data     <= 1'b0;                //7  SDA low = START
                 // enable_external_serial_clock holds (1'b0)         //8
                 out_external_serial_clock    <= 1'b1;                //9  SCL remains high
                 // lat_dev_addr holds previous value                  //10
                 // lat_reg_addr holds previous value                  //11
                 // lat_mosi holds previous value                      //12
                 shift_reg                    <= {lat_dev_addr, 1'b0}; //13 addr + W bit
             end
 
             W_ADDR: begin
                 // state will be conditionally set                    //0
                 // phase will be conditionally set                    //1
                 // bit_cnt will be conditionally set                  //2
                 // ack_latch holds previous value                     //3
                 // busy holds previous value (1'b1)                   //4
                 // miso_data holds previous value                     //5
                 // enable_external_serial_data will be set            //6
                 // out_external_serial_data will be set               //7
                 // enable_external_serial_clock holds (1'b0)         //8
                 // out_external_serial_clock will be set              //9
                 // lat_dev_addr holds previous value                  //10
                 // lat_reg_addr holds previous value                  //11
                 // lat_mosi holds previous value                      //12
                 // shift_reg will be conditionally set                //13
                 case (phase)
                     2'd0: begin
                         phase                       <= 2'd1;         //1
                         enable_external_serial_data <= 1'b0;         //6
                         out_external_serial_data    <= shift_reg[7]; //7
                         out_external_serial_clock   <= 1'b0;         //9
                     end
                     2'd1: begin
                         phase                     <= 2'd2;           //1
                         out_external_serial_clock <= 1'b1;           //9
                     end
                     2'd2: begin
                         phase <= 2'd3;                               //1
                     end
                     2'd3: begin
                         out_external_serial_clock <= 1'b0;           //9
                         if (bit_cnt == 3'd0) begin
                             state <= W_ACK_ADDR;                     //0
                             phase <= 2'd0;                           //1
                         end else begin
                             state     <= W_ADDR;                     //0
                             phase     <= 2'd0;                       //1
                             bit_cnt   <= bit_cnt - 1'd1;             //2
                             shift_reg <= {shift_reg[6:0], 1'b0};     //13
                         end
                     end
                 endcase
             end
 
             W_ACK_ADDR: begin
                 // state will be conditionally set                    //0
                 // phase will be conditionally set                    //1
                 // bit_cnt will be conditionally set                  //2
                 // ack_latch will be set in phase 2                   //3
                 // busy will be conditionally set                     //4
                 // miso_data holds previous value                     //5
                 // enable_external_serial_data will be set            //6
                 // out_external_serial_data holds previous value      //7
                 // enable_external_serial_clock holds (1'b0)         //8
                 // out_external_serial_clock will be set              //9
                 // lat_dev_addr holds previous value                  //10
                 // lat_reg_addr holds previous value                  //11
                 // lat_mosi holds previous value                      //12
                 // shift_reg will be conditionally set                //13
                 case (phase)
                     2'd0: begin
                         phase                       <= 2'd1;         //1
                         enable_external_serial_data <= 1'b1;         //6  release SDA — slave drives ACK
                         out_external_serial_clock   <= 1'b0;         //9
                     end
                     2'd1: begin
                         phase                     <= 2'd2;           //1
                         out_external_serial_clock <= 1'b1;           //9
                     end
                     2'd2: begin
                         phase     <= 2'd3;                           //1
                         ack_latch <= in_external_serial_data;        //3  0=ACK, 1=NACK
                     end
                     2'd3: begin
                         out_external_serial_clock <= 1'b0;           //9
                         if (ack_latch) begin
                             state <= IDLE;                           //0
                             phase <= 2'd0;                           //1
                             busy  <= 1'b0;                           //4
                         end else begin
                             state     <= W_REG;                      //0
                             phase     <= 2'd0;                       //1
                             bit_cnt   <= 3'd7;                       //2
                             shift_reg <= lat_reg_addr;               //13
                         end
                     end
                 endcase
             end
 
             W_REG: begin
                 // state will be conditionally set                    //0
                 // phase will be conditionally set                    //1
                 // bit_cnt will be conditionally set                  //2
                 // ack_latch holds previous value                     //3
                 // busy holds previous value (1'b1)                   //4
                 // miso_data holds previous value                     //5
                 // enable_external_serial_data will be set            //6
                 // out_external_serial_data will be set               //7
                 // enable_external_serial_clock holds (1'b0)         //8
                 // out_external_serial_clock will be set              //9
                 // lat_dev_addr holds previous value                  //10
                 // lat_reg_addr holds previous value                  //11
                 // lat_mosi holds previous value                      //12
                 // shift_reg will be conditionally set                //13
                 case (phase)
                     2'd0: begin
                         phase                       <= 2'd1;         //1
                         enable_external_serial_data <= 1'b0;         //6
                         out_external_serial_data    <= shift_reg[7]; //7
                         out_external_serial_clock   <= 1'b0;         //9
                     end
                     2'd1: begin
                         phase                     <= 2'd2;           //1
                         out_external_serial_clock <= 1'b1;           //9
                     end
                     2'd2: begin
                         phase <= 2'd3;                               //1
                     end
                     2'd3: begin
                         out_external_serial_clock <= 1'b0;           //9
                         if (bit_cnt == 3'd0) begin
                             state <= W_ACK_REG;                      //0
                             phase <= 2'd0;                           //1
                         end else begin
                             state     <= W_REG;                      //0
                             phase     <= 2'd0;                       //1
                             bit_cnt   <= bit_cnt - 1'd1;             //2
                             shift_reg <= {shift_reg[6:0], 1'b0};     //13
                         end
                     end
                 endcase
             end
 
             W_ACK_REG: begin
                 // state will be conditionally set                    //0
                 // phase will be conditionally set                    //1
                 // bit_cnt will be conditionally set                  //2
                 // ack_latch will be set in phase 2                   //3
                 // busy will be conditionally set                     //4
                 // miso_data holds previous value                     //5
                 // enable_external_serial_data will be set            //6
                 // out_external_serial_data holds previous value      //7
                 // enable_external_serial_clock holds (1'b0)         //8
                 // out_external_serial_clock will be set              //9
                 // lat_dev_addr holds previous value                  //10
                 // lat_reg_addr holds previous value                  //11
                 // lat_mosi holds previous value                      //12
                 // shift_reg will be conditionally set                //13
                 case (phase)
                     2'd0: begin
                         phase                       <= 2'd1;         //1
                         enable_external_serial_data <= 1'b1;         //6
                         out_external_serial_clock   <= 1'b0;         //9
                     end
                     2'd1: begin
                         phase                     <= 2'd2;           //1
                         out_external_serial_clock <= 1'b1;           //9
                     end
                     2'd2: begin
                         phase     <= 2'd3;                           //1
                         ack_latch <= in_external_serial_data;        //3
                     end
                     2'd3: begin
                         out_external_serial_clock <= 1'b0;           //9
                         if (ack_latch) begin
                             state <= IDLE;                           //0
                             phase <= 2'd0;                           //1
                             busy  <= 1'b0;                           //4
                         end else begin
                             state     <= W_DATA0;                    //0
                             phase     <= 2'd0;                       //1
                             bit_cnt   <= 3'd7;                       //2
                             shift_reg <= lat_mosi[15:8];             //13 high byte
                         end
                     end
                 endcase
             end
 
             W_DATA0: begin
                 // state will be conditionally set                    //0
                 // phase will be conditionally set                    //1
                 // bit_cnt will be conditionally set                  //2
                 // ack_latch holds previous value                     //3
                 // busy holds previous value (1'b1)                   //4
                 // miso_data holds previous value                     //5
                 // enable_external_serial_data will be set            //6
                 // out_external_serial_data will be set               //7
                 // enable_external_serial_clock holds (1'b0)         //8
                 // out_external_serial_clock will be set              //9
                 // lat_dev_addr holds previous value                  //10
                 // lat_reg_addr holds previous value                  //11
                 // lat_mosi holds previous value                      //12
                 // shift_reg will be conditionally set                //13
                 case (phase)
                     2'd0: begin
                         phase                       <= 2'd1;         //1
                         enable_external_serial_data <= 1'b0;         //6
                         out_external_serial_data    <= shift_reg[7]; //7
                         out_external_serial_clock   <= 1'b0;         //9
                     end
                     2'd1: begin
                         phase                     <= 2'd2;           //1
                         out_external_serial_clock <= 1'b1;           //9
                     end
                     2'd2: begin
                         phase <= 2'd3;                               //1
                     end
                     2'd3: begin
                         out_external_serial_clock <= 1'b0;           //9
                         if (bit_cnt == 3'd0) begin
                             state <= W_ACK_DATA0;                    //0
                             phase <= 2'd0;                           //1
                         end else begin
                             state     <= W_DATA0;                    //0
                             phase     <= 2'd0;                       //1
                             bit_cnt   <= bit_cnt - 1'd1;             //2
                             shift_reg <= {shift_reg[6:0], 1'b0};     //13
                         end
                     end
                 endcase
             end
 
             W_ACK_DATA0: begin
                 // state will be conditionally set                    //0
                 // phase will be conditionally set                    //1
                 // bit_cnt will be conditionally set                  //2
                 // ack_latch will be set in phase 2                   //3
                 // busy will be conditionally set                     //4
                 // miso_data holds previous value                     //5
                 // enable_external_serial_data will be set            //6
                 // out_external_serial_data holds previous value      //7
                 // enable_external_serial_clock holds (1'b0)         //8
                 // out_external_serial_clock will be set              //9
                 // lat_dev_addr holds previous value                  //10
                 // lat_reg_addr holds previous value                  //11
                 // lat_mosi holds previous value                      //12
                 // shift_reg will be conditionally set                //13
                 case (phase)
                     2'd0: begin
                         phase                       <= 2'd1;         //1
                         enable_external_serial_data <= 1'b1;         //6
                         out_external_serial_clock   <= 1'b0;         //9
                     end
                     2'd1: begin
                         phase                     <= 2'd2;           //1
                         out_external_serial_clock <= 1'b1;           //9
                     end
                     2'd2: begin
                         phase     <= 2'd3;                           //1
                         ack_latch <= in_external_serial_data;        //3
                     end
                     2'd3: begin
                         out_external_serial_clock <= 1'b0;           //9
                         if (ack_latch) begin
                             state <= IDLE;                           //0
                             phase <= 2'd0;                           //1
                             busy  <= 1'b0;                           //4
                         end else begin
                             state     <= W_DATA1;                    //0
                             phase     <= 2'd0;                       //1
                             bit_cnt   <= 3'd7;                       //2
                             shift_reg <= lat_mosi[7:0];              //13 low byte
                         end
                     end
                 endcase
             end
 
             W_DATA1: begin
                 // state will be conditionally set                    //0
                 // phase will be conditionally set                    //1
                 // bit_cnt will be conditionally set                  //2
                 // ack_latch holds previous value                     //3
                 // busy holds previous value (1'b1)                   //4
                 // miso_data holds previous value                     //5
                 // enable_external_serial_data will be set            //6
                 // out_external_serial_data will be set               //7
                 // enable_external_serial_clock holds (1'b0)         //8
                 // out_external_serial_clock will be set              //9
                 // lat_dev_addr holds previous value                  //10
                 // lat_reg_addr holds previous value                  //11
                 // lat_mosi holds previous value                      //12
                 // shift_reg will be conditionally set                //13
                 case (phase)
                     2'd0: begin
                         phase                       <= 2'd1;         //1
                         enable_external_serial_data <= 1'b0;         //6
                         out_external_serial_data    <= shift_reg[7]; //7
                         out_external_serial_clock   <= 1'b0;         //9
                     end
                     2'd1: begin
                         phase                     <= 2'd2;           //1
                         out_external_serial_clock <= 1'b1;           //9
                     end
                     2'd2: begin
                         phase <= 2'd3;                               //1
                     end
                     2'd3: begin
                         out_external_serial_clock <= 1'b0;           //9
                         if (bit_cnt == 3'd0) begin
                             state <= W_ACK_DATA1;                    //0
                             phase <= 2'd0;                           //1
                         end else begin
                             state     <= W_DATA1;                    //0
                             phase     <= 2'd0;                       //1
                             bit_cnt   <= bit_cnt - 1'd1;             //2
                             shift_reg <= {shift_reg[6:0], 1'b0};     //13
                         end
                     end
                 endcase
             end
 
             W_ACK_DATA1: begin
                 // state will be conditionally set                    //0
                 // phase will be conditionally set                    //1
                 // bit_cnt holds previous value                       //2
                 // ack_latch will be set in phase 2                   //3
                 // busy will be conditionally set                     //4
                 // miso_data holds previous value                     //5
                 // enable_external_serial_data will be set            //6
                 // out_external_serial_data holds previous value      //7
                 // enable_external_serial_clock holds (1'b0)         //8
                 // out_external_serial_clock will be set              //9
                 // lat_dev_addr holds previous value                  //10
                 // lat_reg_addr holds previous value                  //11
                 // lat_mosi holds previous value                      //12
                 // shift_reg holds previous value                     //13
                 case (phase)
                     2'd0: begin
                         phase                       <= 2'd1;         //1
                         enable_external_serial_data <= 1'b1;         //6
                         out_external_serial_clock   <= 1'b0;         //9
                     end
                     2'd1: begin
                         phase                     <= 2'd2;           //1
                         out_external_serial_clock <= 1'b1;           //9
                     end
                     2'd2: begin
                         phase     <= 2'd3;                           //1
                         ack_latch <= in_external_serial_data;        //3
                     end
                     2'd3: begin
                         out_external_serial_clock <= 1'b0;           //9
                         if (ack_latch) begin
                             state <= IDLE;                           //0
                             phase <= 2'd0;                           //1
                             busy  <= 1'b0;                           //4
                         end else begin
                             state <= W_STOP;                         //0
                             phase <= 2'd0;                           //1
                         end
                     end
                 endcase
             end
 
             W_STOP: begin
                 // state will be conditionally set                    //0
                 // phase will be conditionally set                    //1
                 // bit_cnt holds previous value                       //2
                 // ack_latch holds previous value                     //3
                 // busy will be conditionally set                     //4
                 // miso_data holds previous value                     //5
                 // enable_external_serial_data will be set            //6
                 // out_external_serial_data will be set               //7
                 // enable_external_serial_clock holds (1'b0)         //8
                 // out_external_serial_clock will be set              //9
                 // lat_dev_addr holds previous value                  //10
                 // lat_reg_addr holds previous value                  //11
                 // lat_mosi holds previous value                      //12
                 // shift_reg holds previous value                     //13
                 case (phase)
                     2'd0: begin
                         phase                       <= 2'd1;         //1
                         enable_external_serial_data <= 1'b0;         //6  drive SDA
                         out_external_serial_data    <= 1'b0;         //7  SDA low
                         out_external_serial_clock   <= 1'b0;         //9
                     end
                     2'd1: begin
                         phase                     <= 2'd2;           //1
                         out_external_serial_clock <= 1'b1;           //9  SCL rises
                     end
                     2'd2: begin
                         phase                    <= 2'd3;            //1
                         out_external_serial_data <= 1'b1;            //7  SDA rises = STOP
                     end
                     2'd3: begin
                         state                       <= IDLE;         //0
                         phase                       <= 2'd0;         //1
                         busy                        <= 1'b0;         //4
                         enable_external_serial_data <= 1'b1;         //6  release SDA
                     end
                 endcase
             end
 
             // ================================================================
             // READ BRANCH
             // ================================================================
 
             R_START: begin
                 state                        <= R_ADDR_W;              //0
                 phase                        <= 2'd0;                  //1
                 bit_cnt                      <= 3'd7;                  //2
