                         phase                     <= 2'd2;           //1
                         out_external_serial_clock <= 1'b1;           //9
                     end
                     2'd2: begin
                         phase     <= 2'd3;                           //1
                         ack_latch <= in_external_serial_data;        //3
                     end
                     2'd3: begin
                         out_external_serial_clock <= 1'b0;           //9
                         if (ack_latch) begin
                             state <= IDLE;                           //0
                             phase <= 2'd0;                           //1
                             busy  <= 1'b0;                           //4
                         end else begin
