                     2'd3: begin
                         out_external_serial_clock <= 1'b0;           //9
                         if (ack_latch) begin
                             state <= IDLE;                           //0
                             phase <= 2'd0;                           //1
                             busy  <= 1'b0;                           //4
                         end else begin
                             state <= R_RSTART;                       //0
                             phase <= 2'd0;                           //1
                         end
                     end
                 endcase
